interface PreviewConnectionOptions {
  previewPrefix: string;
  scriptNonce: string;
}

export const PREVIEW_CONNECTIONS_SCRIPT_ID = 'rivet-preview-connections';

export const createPreviewConnectionsScript = ({
  previewPrefix,
  scriptNonce,
}: PreviewConnectionOptions): string => {
  const script = `
(() => {
  const prefix = ${JSON.stringify(previewPrefix).replace(/</g, '\\u003c')};
  const NativeWebSocket = window.WebSocket;
  if (!NativeWebSocket) return;
  window.WebSocket = class extends NativeWebSocket {
    constructor(url, protocols) {
      const target = new URL(url, window.location.href);
      if (
        target.host === window.location.host &&
        ['http:', 'https:', 'ws:', 'wss:'].includes(target.protocol) &&
        !target.pathname.startsWith('/__rivet/preview/')
      ) {
        target.pathname = prefix + target.pathname;
      }
      super(target.href, protocols);
    }
  };
})();
`.trim();
  return `<script id="${PREVIEW_CONNECTIONS_SCRIPT_ID}" nonce="${scriptNonce}">${script}</script>`;
};
